const raw = $json.body ?? $json;
const message = String(raw.message ?? raw.query ?? '').trim();
const userEmail = String(raw.userEmail ?? raw.email ?? '').trim().toLowerCase();
if (!message) throw new Error('message is required');
if (!userEmail) throw new Error('userEmail is required');
return [{ json: { message, userEmail, receivedAt: new Date().toISOString() } }];

function extractJson(text) {
  const raw = String(text || '').trim();
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start === -1 || end === -1 || end <= start) return null;
  return raw.slice(start, end + 1);
}
const source = $json.response ?? $json.data?.response ?? '';
let parsed;
try {
  parsed = JSON.parse(source);
} catch {
  const candidate = extractJson(source);
  parsed = candidate ? JSON.parse(candidate) : null;
}
if (!parsed || typeof parsed !== 'object') {
  return [{ json: { ...$('Normalize Input').item.json, intent: 'ask_clarification', needs_clarification: true, clarification_question: 'I could not reliably understand that request. Can you restate it with the event name and date?', reason: 'Failed to parse model response.' } }];
}
const result = {
  ...$('Normalize Input').item.json,
  intent: typeof parsed.intent === 'string' ? parsed.intent : 'ask_clarification',
  event_title: parsed.event_title ?? null,
  new_title: parsed.new_title ?? null,
  new_description: parsed.new_description ?? null,
  new_location: parsed.new_location ?? null,
  source_date: parsed.source_date ?? null,
  target_date: parsed.target_date ?? null,
  source_time: parsed.source_time ?? null,
  target_time: parsed.target_time ?? null,
  date_range_start: parsed.date_range_start ?? null,
  date_range_end: parsed.date_range_end ?? null,
  participants: Array.isArray(parsed.participants) ? parsed.participants : [],
  calendar_id: parsed.calendar_id || 'primary',
  needs_clarification: Boolean(parsed.needs_clarification),
  clarification_question: parsed.clarification_question ?? null,
  reason: parsed.reason ?? ''
};
if (result.needs_clarification && result.intent !== 'ask_clarification') {
  result.intent = 'ask_clarification';
}
return [{ json: result }];

const parsed = $('Parse Intent Result').item.json;
const events = Array.isArray($json.events) ? $json.events : [];
function formatEvent(event) {
  const when = event.start || event.startAt || 'unknown time';
  return `${event.summary || '(No title)'} at ${when}`;
}
function buildTimedPatch(event, targetDate, targetTime) {
  const originalStart = new Date(event.start || event.startAt);
  const originalEnd = new Date(event.end || event.endAt || event.start || event.startAt);
  const durationMs = Math.max(30 * 60 * 1000, originalEnd.getTime() - originalStart.getTime());
  const datePart = targetDate || originalStart.toISOString().slice(0, 10);
  const timePart = targetTime || `${String(originalStart.getHours()).padStart(2, '0')}:${String(originalStart.getMinutes()).padStart(2, '0')}`;
  const nextStart = new Date(`${datePart}T${timePart}:00`);
  const nextEnd = new Date(nextStart.getTime() + durationMs);
  return {
    start: { dateTime: nextStart.toISOString() },
    end: { dateTime: nextEnd.toISOString() }
  };
}
function buildAllDayPatch(event, targetDate) {
  const startDate = event.start || event.startAt;
  const endDate = event.end || event.endAt || startDate;
  const start = new Date(`${startDate}T00:00:00Z`);
  const end = new Date(`${endDate}T00:00:00Z`);
  const diffDays = Math.max(1, Math.round((end.getTime() - start.getTime()) / 86400000));
  const nextStart = new Date(`${targetDate}T00:00:00Z`);
  const nextEnd = new Date(nextStart.getTime() + diffDays * 86400000);
  return {
    start: { date: nextStart.toISOString().slice(0, 10) },
    end: { date: nextEnd.toISOString().slice(0, 10) }
  };
}
if (parsed.intent === 'view_events') {
  const reply = events.length ? `I found ${events.length} event(s):\n${events.map((event, index) => `${index + 1}. ${formatEvent(event)}`).join('\n')}` : 'I could not find any matching events.';
  return [{ json: { readyForAction: false, response: { ok: true, reply, events } } }];
}
if (!events.length) {
  return [{ json: { readyForAction: false, response: { ok: false, reply: 'I could not find any matching event to modify or delete.' } } }];
}
if (events.length > 1) {
  return [{ json: { readyForAction: false, response: { ok: false, reply: `I found ${events.length} possible matches. Please be more specific:\n${events.map((event, index) => `${index + 1}. ${formatEvent(event)}`).join('\n')}` } } }];
}
const event = events[0];
if (parsed.intent === 'delete_event') {
  return [{ json: { readyForAction: true, method: 'DELETE', url: `http://localhost:3000/api/agent/events/${event.eventId}`, body: { userEmail: parsed.userEmail, sendUpdates: 'all', sync: true }, eventSummary: event.summary || '(No title)' } }];
}
const isAllDay = String(event.start || '').length === 10;
const patch = {};
if (parsed.intent === 'move_event') {
  if (!parsed.target_date && !parsed.target_time) {
    return [{ json: { readyForAction: false, response: { ok: false, reply: 'I need the target date or time to move that event.' } } }];
  }
  Object.assign(patch, isAllDay ? buildAllDayPatch(event, parsed.target_date || parsed.source_date) : buildTimedPatch(event, parsed.target_date, parsed.target_time));
}
if (parsed.intent === 'update_event') {
  if (parsed.new_title) patch.summary = parsed.new_title;
  if (parsed.new_description) patch.description = parsed.new_description;
  if (parsed.new_location) patch.location = parsed.new_location;
  if (parsed.target_date || parsed.target_time) {
    Object.assign(patch, isAllDay ? buildAllDayPatch(event, parsed.target_date || parsed.source_date) : buildTimedPatch(event, parsed.target_date, parsed.target_time));
  }
  if (!Object.keys(patch).length) {
    return [{ json: { readyForAction: false, response: { ok: false, reply: 'I understood this as an update, but I do not have any fields to change yet.' } } }];
  }
}
return [{ json: { readyForAction: true, method: 'PATCH', url: `http://localhost:3000/api/agent/events/${event.eventId}`, body: { userEmail: parsed.userEmail, sendUpdates: 'all', sync: true, ...patch }, eventSummary: event.summary || '(No title)', operation: parsed.intent } }];

const parsed = $('Parse Intent Result').item.json;
if (!parsed.event_title) {
  return [{ json: { response: { ok: false, reply: 'I need the event title to create a new calendar event.' } } }];
}
if (parsed.date_range_start && parsed.date_range_end) {
  return [{ json: { method: 'POST', url: 'http://localhost:3000/api/agent/events', body: { userEmail: parsed.userEmail, summary: parsed.event_title, description: parsed.new_description || '', location: parsed.new_location || '', attendees: parsed.participants || [], start: { dateTime: parsed.date_range_start }, end: { dateTime: parsed.date_range_end }, sendUpdates: 'all', sync: true } } }];
}
if (!parsed.target_date) {
  return [{ json: { response: { ok: false, reply: 'I need a date to create the new event.' } } }];
}
if (!parsed.target_time) {
  const nextDay = new Date(`${parsed.target_date}T00:00:00Z`);
  nextDay.setUTCDate(nextDay.getUTCDate() + 1);
  return [{ json: { method: 'POST', url: 'http://localhost:3000/api/agent/events', body: { userEmail: parsed.userEmail, summary: parsed.event_title, description: parsed.new_description || '', location: parsed.new_location || '', attendees: parsed.participants || [], start: { date: parsed.target_date }, end: { date: nextDay.toISOString().slice(0, 10) }, sendUpdates: 'all', sync: true } } }];
}
const start = new Date(`${parsed.target_date}T${parsed.target_time}:00`);
const end = new Date(start.getTime() + 30 * 60 * 1000);
return [{ json: { method: 'POST', url: 'http://localhost:3000/api/agent/events', body: { userEmail: parsed.userEmail, summary: parsed.event_title, description: parsed.new_description || '', location: parsed.new_location || '', attendees: parsed.participants || [], start: { dateTime: start.toISOString() }, end: { dateTime: end.toISOString() }, sendUpdates: 'all', sync: true } } }];

const payload = $json.response ? $json.response : $json;
const response = payload.response || payload;
return [{ json: response }];

const created = $json.event || {};
const title = created.summary || $('Parse Intent Result').item.json.event_title || '(No title)';
const when = created.start?.dateTime || created.start?.date || 'the requested time';
return [{ json: { ok: true, reply: `Created '${title}' for ${when}.`, event: created } }];

const action = $('Handle Search Result').item.json;
const parsed = $('Parse Intent Result').item.json;
const label = action.eventSummary || 'the event';
let reply = `Updated '${label}'.`;
if (parsed.intent === 'delete_event') reply = `Deleted '${label}'.`;
if (parsed.intent === 'move_event') reply = `Moved '${label}' to the requested time.`;
return [{ json: { ok: true, reply, event: $json.event || null } }];

const parsed = $('Parse Intent Result').item.json;
const reply = parsed.clarification_question || `I need a bit more detail before I can act on this request.`;
return [{ json: { ok: false, reply, reason: parsed.reason || '' } }];
